import{_ as s,C as i,o as a,c,aj as n,E as d,j as e,a as o}from"./framework.js";const D=JSON.parse('{"title":"Discounts | Commerce | Admin CMS","description":"Configure site discount rules: can apply automatically when conditions are met, or via discount codes entered by customers/admin in carts. Cart and checkout trial calculation uses the…","frontmatter":{"title":"Discounts | Commerce | Admin CMS","description":"Configure site discount rules: can apply automatically when conditions are met, or via discount codes entered by customers/admin in carts. Cart and checkout trial calculation uses the…","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/commerce/discounts.html"}]]},"headers":[],"relativePath":"cms/commerce/discounts.md","filePath":"en/cms/commerce/discounts.md","lastUpdated":1781010536000}'),l={name:"cms/commerce/discounts.md"};function u(g,t,m,h,p,b){const r=i("DocImage");return a(),c("div",null,[t[0]||(t[0]=n('<h1 id="discounts" tabindex="-1">Discounts <a class="header-anchor" href="#discounts" aria-label="Permalink to &quot;Discounts&quot;">​</a></h1><blockquote><p>Menu: <strong>Commerce -&gt; Discounts</strong><br> Deep link: <code>/_Admin/commerce/discounts?SiteId={siteGuid}</code><br><strong>Create</strong>: <code>/_Admin/commerce/discounts/create?SiteId=...</code><br><strong>Edit</strong>: <code>/_Admin/commerce/discounts/edit?SiteId=...&amp;id={discountId}</code></p></blockquote><p>Configure site <strong>discount rules</strong>: can apply <strong>automatically</strong> when conditions are met, or via <strong>discount codes</strong> entered by customers/admin in <a href="./carts.html">carts</a>. Cart and checkout trial calculation uses the server discount engine; script API: <a href="/kb-docs/api/commerce/discount.html">k.commerce.discount</a>.</p><h2 id="how-to-open" tabindex="-1">How to Open <a class="header-anchor" href="#how-to-open" aria-label="Permalink to &quot;How to Open&quot;">​</a></h2><ol><li>In the <a href="./../navigation.html#edit-menu">Edit menu</a>, enable <strong>Commerce -&gt; Discounts</strong> (and the parent <strong>Commerce</strong> group).</li><li>Open <strong>Commerce -&gt; Discounts</strong> in the left sidebar.</li></ol><h2 id="list-page" tabindex="-1">List Page <a class="header-anchor" href="#list-page" aria-label="Permalink to &quot;List Page&quot;">​</a></h2><p>Path: <code>/_Admin/commerce/discounts?SiteId=...</code></p><table tabindex="0"><thead><tr><th>Column / Action</th><th>Description</th></tr></thead><tbody><tr><td><strong>Title</strong></td><td>Rule name (<code>title</code>)</td></tr><tr><td><strong>Discount code</strong></td><td>When method is <strong>discount code</strong>, shows <code>code</code> as tag; empty for automatic discounts</td></tr><tr><td><strong>Conditions</strong></td><td>Multiple condition summaries joined by <strong>AND</strong> / <strong>OR</strong></td></tr><tr><td><strong>Priority</strong></td><td>Number <code>priority</code>; sort order when multiple rules match</td></tr><tr><td><strong>Exclusive</strong></td><td><strong>Yes</strong> means <strong>exclusive</strong> with other discounts (<code>isExclusion</code>)</td></tr><tr><td><strong>Active period</strong></td><td>Start ~ end; not started / active / expired shown in color</td></tr><tr><td><strong>Usage</strong></td><td>Discount code usage count; if capped, shows <code>used/limit</code></td></tr><tr><td><strong>Details</strong></td><td>Tags: <strong>Product</strong> / <strong>Order</strong> / <strong>Free shipping</strong>, plus <code>-amount</code> or <code>-percentage</code></td></tr><tr><td><strong>Create</strong></td><td>Opens <a href="#create-and-edit">Create and edit</a></td></tr><tr><td><strong>Discounted orders</strong></td><td>Row search icon opens <a href="#discounted-orders-dialog">Discounted orders dialog</a></td></tr><tr><td><strong>Edit</strong></td><td>Row pencil opens edit page</td></tr><tr><td><strong>Batch delete</strong></td><td>Select rows → <strong>Delete</strong> → confirm</td></tr></tbody></table>',8)),d(r,{src:"/cms/commerce/discounts-list.png",alt:"Discounts list: codes, conditions, priority and usage",width:"1120"}),t[1]||(t[1]=n('<h3 id="discounted-orders-dialog" tabindex="-1">Discounted Orders Dialog <a class="header-anchor" href="#discounted-orders-dialog" aria-label="Permalink to &quot;Discounted Orders Dialog&quot;">​</a></h3><p>Click <strong>Discounted orders</strong> (advanced search icon) on a list row to open a paginated dialog of <a href="./orders.html">orders</a> that applied this rule:</p><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Order ID</strong></td><td>Order Id</td></tr><tr><td><strong>Total amount</strong></td><td>Original/current price (<code>CurrencyAmount</code>)</td></tr><tr><td><strong>Order status</strong></td><td>Status component</td></tr><tr><td><strong>Customer</strong></td><td>Email, phone</td></tr><tr><td><strong>Created</strong></td><td>Order time</td></tr></tbody></table>',3)),d(r,{src:"/cms/commerce/discounts-orders-dialog.png",alt:"Discounted orders dialog: order list and pagination",width:"960"}),t[2]||(t[2]=e("h2",{id:"create-and-edit",tabindex:"-1"},[o("Create and Edit "),e("a",{class:"header-anchor",href:"#create-and-edit","aria-label":'Permalink to "Create and Edit"'},"​")],-1)),t[3]||(t[3]=e("p",null,[o("Path: "),e("code",null,"/_Admin/commerce/discounts/create?SiteId=..."),o(" or "),e("code",null,".../edit?SiteId=...&id=...")],-1)),t[4]||(t[4]=e("p",null,[o("Breadcrumb: "),e("strong",null,"Discounts -> Create / Edit"),o(". Form has three card sections.")],-1)),d(r,{src:"/cms/commerce/discounts-edit.png",alt:"Discount edit: title, method, type, conditions",width:"1120"}),t[5]||(t[5]=n('<h3 id="basic-information" tabindex="-1">Basic Information <a class="header-anchor" href="#basic-information" aria-label="Permalink to &quot;Basic Information&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Title</strong></td><td>Rule name for list and admin identification</td></tr><tr><td><strong>Active period</strong></td><td>Start and end date/time; rule inactive outside range</td></tr><tr><td><strong>Priority</strong></td><td>Integer; sort when multiple rules match</td></tr><tr><td><strong>Method</strong></td><td><strong>Automatic discount</strong>: applies when conditions met; <strong>Discount code</strong>: requires code entry (below)</td></tr><tr><td><strong>Discount code</strong></td><td>Shown only for <strong>discount code</strong> method: code text (create page can auto-generate 6 uppercase chars), optional <strong>usage limit</strong> and cap</td></tr><tr><td><strong>Exclusive</strong></td><td>When enabled, exclusive with other discounts (<code>isExclusion</code>)</td></tr></tbody></table><p><a href="./carts.html#discount-codes">Discount codes below the cart product table</a> can only use saved rules with <strong>discount code</strong> method here.</p><h3 id="discount-type-and-amount" tabindex="-1">Discount Type and Amount <a class="header-anchor" href="#discount-type-and-amount" aria-label="Permalink to &quot;Discount Type and Amount&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>Product amount off</strong> (<code>ProductAmountOff</code>)</td><td>Reduces qualifying <strong>order lines</strong>; condition schema is &quot;order product&quot; dimension</td></tr><tr><td><strong>Order amount off</strong> (<code>OrderAmountOff</code>)</td><td>Reduces entire order; condition schema is &quot;order&quot; dimension</td></tr><tr><td><strong>Free shipping</strong> (<code>FreeShipping</code>)</td><td>Waives shipping; no amount/percentage</td></tr></tbody></table><p>When not free shipping, choose <strong>fixed amount</strong> or <strong>percentage</strong> and enter <code>value</code> (suffix is site <code>currencyCode</code> or <code>%</code>).</p><p>Changing <strong>type</strong> clears existing <strong>conditions</strong> and reloads the corresponding condition field list.</p><h3 id="applicable-conditions" tabindex="-1">Applicable Conditions <a class="header-anchor" href="#applicable-conditions" aria-label="Permalink to &quot;Applicable Conditions&quot;">​</a></h3><p>Uses the shared <strong>Condition</strong> component:</p><table tabindex="0"><thead><tr><th>Item</th><th>Description</th></tr></thead><tbody><tr><td><strong>Match</strong></td><td><strong>All conditions</strong> (AND) or <strong>Any condition</strong> (OR)</td></tr><tr><td><strong>Condition rows</strong></td><td>Field (dropdown, varies by type) + comparison + value; <strong>Add</strong> / <strong>Delete</strong> rows</td></tr></tbody></table><p>For example: minimum order amount, specific products/categories, customer tags, etc. (available fields from server <code>getOrderLineSchemas</code> / <code>getOrderSchemas</code>).</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./carts.html">Carts</a> — enter discount codes during trial calculation</li><li><a href="./orders.html">Orders</a> — view discounted orders after purchase</li><li><a href="./product-management.html">Product management</a>, <a href="./product-categories.html">Product categories</a> — conditions often reference product scope</li><li><a href="/kb-docs/api/commerce/discount.html">k.commerce.discount</a></li></ul>',13))])}const C=s(l,[["render",u]]);export{D as __pageData,C as default};
